import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import {
  agentsBlockLineCount,
  renderAgentsBlock,
  renderAgentsBlockBody,
  renderPipelineEntry,
} from "../../../src/core/build/index.js";
import { loadFactory } from "../../../src/core/factory/index.js";
import type { Factory } from "../../../src/core/factory/types.js";

const FIXTURE = fileURLToPath(
  new URL("../../fixtures/build/mark4-like/source", import.meta.url),
);

const EXPECTED_BLOCK = `<!-- factory:start -->
<!-- Generated by metafab build from .factory/. Edit the source, then run metafab build. -->

# Mark4 factory

Build and review work in slices.

## Pipeline

Work moves through these workflows in order. When one ends, suggest the next.

1. \`file-work\`
2. \`triage-ideas\`. Then stop: The product lead picks the next item.
3. \`plan-feature\`. Then stop: The tech lead approves the plan as a documentation PR.
4. \`build-slice\`
5. \`review-slice\`. Then stop: The code owner approves the PR.
6. \`finish-slice\`

## Factory source

This repository stores its factory in \`.factory/\`. Edit that directory and run \`metafab build\`.
Do not edit installed copies in \`.claude/\` or \`.agents/\`.
<!-- factory:end -->`;

function factoryWith(overrides: Partial<Factory>): Factory {
  return {
    root: "/repo",
    dir: "/repo/.factory",
    skills: [],
    problems: [],
    ...overrides,
  };
}

describe("AGENTS.md renderer", () => {
  test("renders the mark4-like block exactly as the spec", async () => {
    const factory = await loadFactory(FIXTURE);

    expect(renderAgentsBlock(factory)).toBe(EXPECTED_BLOCK);
    expect(renderAgentsBlockBody(factory)).toBe(
      EXPECTED_BLOCK.split("\n").slice(1, -1).join("\n"),
    );
  });

  test("renders a stop entry without lowercasing its text", () => {
    expect(
      renderPipelineEntry({ workflow: "review", stop: "Kat approves the PR", line: 1 }, 0),
    ).toBe("1. `review`. Then stop: Kat approves the PR.");
  });

  test("keeps terminal punctuation on the stop text", () => {
    expect(renderPipelineEntry({ workflow: "review", stop: "Kat approves.", line: 1 }, 0)).toBe(
      "1. `review`. Then stop: Kat approves.",
    );
  });

  test("omits the pipeline section when there is no pipeline", () => {
    const block = renderAgentsBlock(factoryWith({ agentsMd: "# Standing\n" }));

    expect(block).toContain("<!-- Generated by metafab build from .factory/.");
    expect(block).toContain("# Standing");
    expect(block).not.toContain("## Pipeline");
    expect(block).toContain("## Factory source");
  });

  test("omits the standing instructions section when .factory/AGENTS.md is empty", () => {
    const block = renderAgentsBlock(factoryWith({ agentsMd: "\n \n" }));

    expect(block).toContain(
      "<!-- Generated by metafab build from .factory/. Edit the source, then run metafab build. -->\n\n## Factory source",
    );
  });

  test("counts the full block, markers included", () => {
    const factory = factoryWith({ agentsMd: Array.from({ length: 300 }, () => "line").join("\n") });

    expect(agentsBlockLineCount(factory)).toBeGreaterThan(300);
  });
});
